// Ordering for the bundled built-in deck corpus (old-webui parity).
//
// The committed asset (`bundledDecks.generated.json`) carries the source
// corpus's FILE order — `builtin.json` is generated by walking the mtgtop8
// directories — which is neither grouped nor alphabetical. A Create-Table
// dropdown listing 5,013 decks in that order is unusable ("isn't sorted like
// our old webUI was ... impossible to pick from").
//
// This module reproduces the ordering of the webui this port replaces
// (`xmage/Mage.WebProxy/web/frontend/react/src/components/deckeditor/
// BuiltInDeckPicker.tsx`, `buildTree`): the event formats lead the library list
// in a fixed order, every other library follows alphabetically, and a library's
// decks are sorted by name. The seat pickers render one <optgroup> per library,
// which is the flat-<select> equivalent of that picker's library → deck nesting.

import type { BundledDeckEntry } from './builtinDecklist'
import type { Deck } from '../lobby/decks'

/** Event formats, in the old picker's order — they lead the library list. */
const EVENT_LIBRARIES = ['Legacy', 'Modern', 'Pioneer', 'Vintage', 'cEDH']

/**
 * `group` tag for the decks compiled into `lobby/decks.ts` (the 9 sample decks
 * that ship in the bundle). They are not part of the corpus corpus, so they get
 * their own picker section instead of joining a corpus library.
 */
export const SAMPLE_DECKS_GROUP = 'samples'

/** Library order: the event formats first (fixed order), then alphabetical. */
export function compareLibraries(a: string, b: string): number {
  const ai = EVENT_LIBRARIES.indexOf(a)
  const bi = EVENT_LIBRARIES.indexOf(b)
  if (ai !== -1 || bi !== -1) {
    if (ai === -1) return 1
    if (bi === -1) return -1
    return ai - bi
  }
  return a.localeCompare(b)
}

/**
 * Decks A–Z. Ties (the corpus carries duplicate names, e.g. two '4c Delver'
 * lists from the same event) break on the id so the order is stable.
 */
export function sortDecksByName<T extends { name: string; id?: string }>(decks: T[]): T[] {
  return [...decks].sort(
    (a, b) => a.name.localeCompare(b.name) || String(a.id ?? '').localeCompare(String(b.id ?? '')),
  )
}

/** Corpus entries in the old picker's order: library, then deck name. */
export function sortBundledEntries(entries: BundledDeckEntry[]): BundledDeckEntry[] {
  return [...entries].sort(
    (a, b) => compareLibraries(a.group, b.group) || a.name.localeCompare(b.name) || a.id.localeCompare(b.id),
  )
}

/**
 * One <optgroup> of a deck picker. `labelKey` is an i18n key inside the `decks`
 * namespace (the player's own decks / the bundled samples); `library` is corpus
 * DATA (the library name, rendered with its deck count) and is never translated.
 */
export interface DeckSection {
  key: string
  labelKey?: 'my_decks' | 'browser_filter_precon'
  library?: string
  decks: Deck[]
}

/**
 * Split a deck list into the picker's sections in display order: the player's
 * own decks first (the old picker kept saved decks as the first list), then the
 * bundled samples, then one section per corpus library in `compareLibraries`
 * order. Every section is sorted by deck name.
 */
export function deckPickerSections(decks: Deck[]): DeckSection[] {
  const own: Deck[] = []
  const samples: Deck[] = []
  const byLibrary = new Map<string, Deck[]>()
  for (const deck of decks) {
    if (deck.group === SAMPLE_DECKS_GROUP) {
      samples.push(deck)
    } else if (deck.group) {
      const list = byLibrary.get(deck.group)
      if (list) list.push(deck)
      else byLibrary.set(deck.group, [deck])
    } else {
      own.push(deck)
    }
  }
  const sections: DeckSection[] = []
  if (own.length > 0) sections.push({ key: 'own', labelKey: 'my_decks', decks: sortDecksByName(own) })
  if (samples.length > 0) sections.push({ key: 'samples', labelKey: 'browser_filter_precon', decks: sortDecksByName(samples) })
  for (const library of [...byLibrary.keys()].sort(compareLibraries)) {
    sections.push({ key: `library:${library}`, library, decks: sortDecksByName(byLibrary.get(library)!) })
  }
  return sections
}
